import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // Fuzzed params: newLimit is the amount passed to AdjustBetAmounts,
    // caller is the address attempting the call. The property:
    // -- In the reference, only the owner (deployer) may change betLimit; any other caller's attempt must not change betLimit.
    // We test that for any inputs, if a non-owner calls AdjustBetAmounts, the betLimit remains equal to the prior value.
    function testFuzz_property(uint256 newLimit, address caller) public {
        // Keep domain wide but avoid the zero address for caller to be meaningful
        vm.assume(caller != address(0));

        // Record prior betLimit
        uint256 before = c.currentBetLimit();

        // If caller is the owner (this test deployer), then changing is allowed by reference; we only need to assert
        // that NON-OWNERS cannot change betLimit. So skip cases where caller == owner.
        address owner = address(this);
        if (caller == owner) {
            // For owner calls we do nothing further; still satisfy fuzzer requirement that function takes params.
            // We assert a tautology that the betLimit is equal to itself (this will always pass).
            assertTrue(c.currentBetLimit() == before);
            return;
        }

        // Try to have 'caller' invoke AdjustBetAmounts
        vm.prank(caller);
        bool ok;
        try c.AdjustBetAmounts(newLimit) { ok = true; } catch { ok = false; }

        // GENERAL ASSERTION (single assert): For any non-owner caller, the correct contract prevents changing betLimit.
        // Thus after the call attempt by a non-owner, betLimit must remain equal to the previous value.
        // The buggy mutant (which removes the onlyOwner require) will allow some non-owner to succeed and change betLimit,
        // making this assertion fail for those inputs.
        assertTrue(c.currentBetLimit() == before);
    }
}

