contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // Fuzzed params: caller address (actor) and newLimit to attempt to change betLimit
    function testFuzz_property(address actor, uint256 newLimit) public {
        // Keep actor non-zero to be a meaningful caller; allow owner (this) too — property must hold for all
        vm.assume(actor != address(0));
        // Ensure actor has some ETH so a call (if payable) won't fail due to lack of funds
        vm.deal(actor, 1 ether);

        // Read original limit
        uint256 before = c.currentBetLimit();

        // Try to have 'actor' call AdjustBetAmounts(newLimit).
        // We capture whether the call succeeded (ok) and then read the betLimit afterwards.
        bool ok;
        uint256 after;
        // Use try/catch to catch reverts vs success
        vm.prank(actor);
        try c.AdjustBetAmounts(newLimit) {
            ok = true;
        } catch {
            ok = false;
        }
        after = c.currentBetLimit();

        // General rule to assert: For the reference contract, if the caller is NOT the owner (actor != address(this)), then the call must NOT change betLimit.
        // This single assertion is true for all inputs on the reference, and the mutant (which removes onlyOwner) will allow some actor to change betLimit,
        // making the assertion false for those inputs.
        if (actor != address(this)) {
            // The call must either revert (ok == false) OR succeed but leave betLimit unchanged (after == before).
            // Combine into one boolean for assertTrue
            bool preserved = (!ok) || (after == before);
            assertTrue(preserved);
        } else {
            // If actor is the owner, the owner is allowed to change the limit; no invariant to check other than consistency of getter, so assert that
            // after equals newLimit when call succeeded, or unchanged when it failed (should not fail for owner in reference, but keep general)
            bool owner_ok = (!ok && after == before) || (ok && after == newLimit);
            assertTrue(owner_ok);
        }
    }
}

