    function testFuzz_property(address actor, uint256 amt) public {
        // Keep actor as any possible address; if actor equals the owner (this contract) the reference will allow the change.
        // We want the general property: non-owners cannot change betLimit. So only assert when actor is NOT the owner.
        // Determine owner by noting that in constructor owner = msg.sender, which was address(this) in setUp().
        // If actor == address(this) then both reference and mutant will set betLimit to amt; that does not distinguish.

        // Ensure actor is not the contract itself to exercise the non-owner path (fuzzer can still try owner, that's fine)
        vm.assume(actor != address(0)); // keep domain wide, avoid zero which is still admissible but unnecessary to exclude

        // Record pre-call betLimit
        uint256 before = c.currentBetLimit();

        // Try to call AdjustBetAmounts as the fuzzed actor; capture whether call succeeded
        bool ok;
        vm.prank(actor);
        try c.AdjustBetAmounts(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, read betLimit
        uint256 after = c.currentBetLimit();

        // General property (single assertion): for any actor != the owner (address(this)), the reference contract must NOT allow them to change the betLimit.
